/**
 * Read-only adversarial acceptance gate for an AI-discovered relational model.
 * Run: node tests/engine/evaluate-commercial-discovery.mjs path/to/model-output.json
 * The candidate must be generated by the real Engine discovery model; this
 * evaluator never manufactures a proposal or writes business records.
 */
import { readFileSync } from "node:fs";

export function evaluateCommercialDiscovery(proposal) {
  const entities = Array.isArray(proposal?.entities) ? proposal.entities : [];
  const relations = Array.isArray(proposal?.relations) ? proposal.relations : [];
  const haystack = entity => [entity.key, entity.name, entity.description].join(" ").toLowerCase();
  const find = pattern => entities.filter(entity => pattern.test(haystack(entity)));
  const fieldText = entity => (entity?.fields ?? []).map(f => [f.key, f.name].join(" ").toLowerCase()).join(" ");
  const checks = [];
  const check = (name, passed, detail) => checks.push({ name, passed: !!passed, detail });
  const products = find(/producto|product|material|art[ií]culo|item/);
  const recipes = find(/receta|recipe|f[oó]rmula/);
  const components = find(/componente|component|ingrediente.*receta|recipe.*item|recipe.*line|l[ií]nea.*receta/);
  const suppliers = find(/proveedor|supplier/);
  const offers = find(/oferta|offer|cotizaci[oó]n|tarifa/);
  const tiers = find(/tramo|tier|escal[oó]n|rapel|rappel|descuento.*volumen|volume.*discount/);
  const product = products[0], recipe = recipes[0], component = components[0],
    supplier = suppliers.find(e => !/oferta|offer/.test(haystack(e))),
    offer = offers[0], tier = tiers[0];
  check("one canonical product entity (inputs and outputs)", products.length === 1,
    products.map(e => e.key));
  check("no separate ingredient master", !entities.some(e => /^(ingredient|ingrediente|raw_material|materia_prima)$/.test(e.key)),
    entities.map(e => e.key));
  check("recipe entity", recipes.length >= 1, recipes.map(e => e.key));
  check("recipe line associative entity", !!component && /cantidad|quantity|unidad|unit/.test(fieldText(component)),
    components.map(e => ({ key: e.key, fields: fieldText(e) })));
  check("supplier entity", !!supplier && /nif|tax|cif|fiscal/.test(fieldText(supplier)),
    suppliers.map(e => ({ key: e.key, fields: fieldText(e) })));
  check("supplier-product offer entity", !!offer && /precio|price/.test(fieldText(offer)),
    offers.map(e => ({ key: e.key, fields: fieldText(e) })));
  check("volume rebate tier entity", !!tier && /cantidad|quantity|m[ií]nimo|minimum|desde/.test(fieldText(tier))
    && /descuento|discount|porcentaje|percent/.test(fieldText(tier)),
    tiers.map(e => ({ key: e.key, fields: fieldText(e) })));
  const connected = (a,b) => !!a && !!b && relations.some(r =>
    (r.fromEntity === a.key && r.toEntity === b.key) ||
    (r.fromEntity === b.key && r.toEntity === a.key));
  check("recipe to recipe line relationship", connected(recipe, component));
  check("recipe line to product relationship", connected(component, product));
  check("recipe output product relationship", connected(recipe, product));
  check("supplier to offer relationship", connected(supplier, offer));
  check("offer to product relationship", connected(offer, product));
  check("offer to rebate tier relationship", connected(offer, tier));
  return { passed: checks.filter(c => c.passed).length, total: checks.length,
    success: checks.every(c => c.passed), checks };
}

if (process.argv[1]?.endsWith("evaluate-commercial-discovery.mjs")) {
  if (!process.argv[2]) {
    console.error("Usage: node tests/engine/evaluate-commercial-discovery.mjs <model-output.json>");
    process.exitCode = 2;
  } else {
    const result = evaluateCommercialDiscovery(JSON.parse(readFileSync(process.argv[2], "utf8")));
    console.log(JSON.stringify(result, null, 2));
    if (!result.success) process.exitCode = 1;
  }
}
